def extract_text_messages(p, n=12):
    data=json.load(open(p,encoding='utf-8'))
    msgs=[]
    for node in data.get('mapping',{}).values():
        m=node.get('message')
        if not m: continue
        role=(m.get('author') or {}).get('role')
        if role not in ('user','assistant'): continue
        c=m.get('content') or {}
        ctype=c.get('content_type')
        parts=c.get('parts')
        text=""
        if isinstance(parts,list):
            vals=[]
            for part in parts:
                if isinstance(part,str): vals.append(part)
                elif isinstance(part,dict):
                    # maybe text field
                    if 'text' in part and isinstance(part['text'],str): vals.append(part['text'])
            text="\n".join(vals)
        elif ctype=='text' and isinstance(c.get('text'),str):
            text=c['text']
        if text.strip():
            msgs.append((m.get('create_time') or 0, role, text.strip()))
    msgs.sort()
    return msgs[-n:]
