import math, cmath
def endpoints(nu, delta=1, L=0.6, gamma=math.pi/2, N=10):
    C=delta + L*cmath.exp(1j*gamma)
    pts=[cmath.exp(1j*(2*math.pi*nu*j))*C for j in range(N)]
    return pts, abs(C), cmath.phase(C)
for nu in [1/3,2/5,(math.sqrt(5)-1)/2]:
    pts,R,shift=endpoints(nu,N=10)
    print(nu,R,shift,[complex(round(z.real,3), round(z.imag,3)) for z in pts[:6]])

